CREATE TEMP TABLE pm_present (kind text, name text) ON COMMIT DROP;

-- ───────────────────────────── the preconditions ──────────────────────────────
DO $$
DECLARE have int;
BEGIN
  IF to_regtype('"Role"') IS NULL OR to_regclass('action_log') IS NULL THEN
    RAISE EXCEPTION 'purchase-module: "Role" or action_log is missing, so this is not the ERP database. Nothing was changed.';
  END IF;
  SELECT count(*) INTO have FROM pm_expected WHERE kind = 'table' AND to_regclass(name) IS NOT NULL;
  IF have > 0 AND have < 84 THEN
    RAISE EXCEPTION 'purchase-module: % of the module''s 84 tables are already there. A part-made module is a person''s call: compare the database with merge/purchase-schema-block.prisma first. Nothing was changed.', have;
  END IF;
  -- What is there before: what the log will not count as added.
  INSERT INTO pm_present
    SELECT kind, name FROM pm_expected
     WHERE (kind = 'type' AND to_regtype(name) IS NOT NULL)
        OR (kind IN ('table', 'index') AND to_regclass(name) IS NOT NULL)
        OR (kind = 'constraint' AND EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conname = name AND c.connamespace = current_schema()::regnamespace));
END $$;

-- ─────────────────────────────── the module ───────────────────────────────────
DO $$ BEGIN
  CREATE TYPE "purchase_doc_status" AS ENUM ('Draft', 'Submitted', 'Cancelled');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_workflow_state" AS ENUM ('Created', 'Approved', 'Rejected');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_order_status" AS ENUM ('Draft', 'On Hold', 'To Receive and Bill', 'To Bill', 'To Receive', 'Completed', 'Cancelled', 'Closed', 'Delivered');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_apply_discount_on" AS ENUM ('Grand Total', 'Net Total');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_tax_charge_type" AS ENUM ('Actual', 'On Net Total', 'On Previous Row Amount', 'On Previous Row Total', 'On Item Quantity');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_tax_consider_for" AS ENUM ('Total', 'Valuation', 'Valuation and Total');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_tax_add_deduct" AS ENUM ('Add', 'Deduct');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_margin_type" AS ENUM ('Percentage', 'Amount');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

DO $$ BEGIN
  CREATE TYPE "purchase_order_event_kind" AS ENUM ('Version', 'Workflow', 'Label', 'Comment', 'Attachment', 'Email', 'Deleted', 'Info');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

